
import type { MoneyValue } from './MoneyValue.js';

export type BuyerGiftCardTransaction = { /** Signed monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "amount_money": { /** Signed amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; "balance_after_money": MoneyValue; "balance_before_money": MoneyValue; "gift_card_id": string; "gift_card_transaction_id": string; /** RFC3339 timestamp. Format: date-time. */ "posted_at": string; /** Use an exact numeric string, not a floating-point number. Format: int64. */ "sequence": string; "transaction_type": "load" | "import" | "redeem" | "refund" | "refund_transfer" | "adjustment" | "cash_out" | "purchase_reversal" | "funding_loss_accepted" | "purchase_refund_recovery" | "purchase_refund_recovery_transfer" | (string & {}); };
